        };

        private static readonly string[][] SortOrderChoices =
        {
            A("High to low","Élevé vers faible","Alto → basso","Hoch nach niedrig","Alto a bajo","高→低","높음→낮음","Alto para baixo","От высокого к низкому","从高到低","Yüksekten düşüğe"),
            A("Low to high","Faible vers élevé","Basso → alto","Niedrig nach hoch","Bajo a alto","低→高","낮음→높음","Baixo para alto","От низкого к высокому","从低到高","Düşükten yükseğe"),
        };

        public static MarkerOptionLocalizedText Resolve(ConfigEntryBase entry)
            => ResolveForLanguage(entry.Definition.Key, ResolveLanguageIndex());

        public static string ResolveCategory(ConfigEntryBase entry)
            => string.Equals(entry.Definition.Key, "ShareTemporaryItems", StringComparison.Ordinal)
                ? GeneralCategoryNames[NormalizeLanguageIndex(ResolveLanguageIndex())]
                : ResolveCategoryForLanguage(entry.Definition.Section, ResolveLanguageIndex());

        internal static string ResolveCategoryForLanguage(string section, int languageIndex)
        {
            var i = NormalizeLanguageIndex(languageIndex);
            return string.Equals(section, "Marker Colors", StringComparison.Ordinal) ? MarkerColorCategoryNames[i] : MarkerCategoryNames[i];
        }

        internal static string CurrentLanguageKey()
            => NormalizeLanguageKey(Language.currentLanguageName);

        internal static MarkerOptionLocalizedText ResolveForLanguage(string key, int languageIndex)
        {
            var i = NormalizeLanguageIndex(languageIndex);
            if (!OptionNames.TryGetValue(key, out var names)) names = A(key,key,key,key,key,key,key,key,key,key,key);
            if (!OptionDescriptions.TryGetValue(key, out var descriptions))
                descriptions = A("ItemShareFix marker option.","Option de marqueur ItemShareFix.","Opzione marker ItemShareFix.","ItemShareFix-Markeroption.","Opción de marcador ItemShareFix.","ItemShareFix マーカー設定。","ItemShareFix 마커 옵션.","Opção de marcador ItemShareFix.","Параметр меток ItemShareFix.","ItemShareFix 标记选项。","ItemShareFix işaretçi seçeneği.");
            return new MarkerOptionLocalizedText(names[i], descriptions[i]);
        }

        public static string[] PresentationModeChoices() => ChoiceForLanguage(PresentationChoices, ResolveLanguageIndex());
        public static string[] SortChoices() => ChoiceForLanguage(SortOrderChoices, ResolveLanguageIndex());

        private static string[] ChoiceForLanguage(string[][] table, int languageIndex)
        {
            var i = NormalizeLanguageIndex(languageIndex);
            var result = new string[table.Length];
            for (var row = 0; row < table.Length; row++) result[row] = table[row][i];
            return result;
        }

        private static int NormalizeLanguageIndex(int index) => index >= 0 && index < SupportedLanguages.Length ? index : 0;

        private static int ResolveLanguageIndex()
            => ResolveLanguageIndexForName(Language.currentLanguageName);

        internal static int ResolveLanguageIndexForName(string? raw)
        {
            var key = NormalizeLanguageKey(raw);
            if (key.Contains("french") || key.StartsWith("fr")) return 1;
            if (key.Contains("italian") || key.StartsWith("it")) return 2;
            if (key.Contains("german") || key.StartsWith("de")) return 3;
            if (key.Contains("spanish") || key.StartsWith("es")) return 4;
            if (key.Contains("japanese") || key.StartsWith("ja")) return 5;
            if (key.Contains("korean") || key.StartsWith("ko")) return 6;
            if (key.Contains("portuguese") || key.StartsWith("pt")) return 7;
            if (key.Contains("russian") || key.StartsWith("ru")) return 8;
            if (key.Contains("chinese") || key.StartsWith("zh")) return 9;
            if (key.Contains("turkish") || key.StartsWith("tr")) return 10;
            return 0;
        }

        private static string NormalizeLanguageKey(string? raw)
            => (raw ?? string.Empty).Trim().ToLowerInvariant();

        private static string[] A(params string[] values) => values;
    }
